solution.solution.py:
def waiting_times(bursts):
    waits = []
    clock = 0
    for burst in bursts:
        waits.append(clock)
        clock += burst
    return waits

def average_wait(bursts):
    waits = waiting_times(bursts)
    return sum(waits) / len(waits)

